Ext._define('esocial.qualification.LoaderFile', {
    extend: 'Ext.Window',
    getFormPanel: function(cfg) {
        if(!this.formPanel)
            this.formPanel = new Ext.form.FormPanel({
                items: [
                    {
                        fieldLabel: 'Arquivo',
                        xtype: 'ged-fileuploadfield',
                        name: 'file',
                        allowBlank: false,
                    }
                ],
            });

        return this.formPanel;
    },

    execute: function(){
        var form = this.getFormPanel().getForm();

        form.waitMsgTarget = this.getFormPanel().getEl();
        form.submit({
            url: toolkit.util.Normalize.controller_action('ESCRegistrationQualification', 'qualificate'),
            failure: function(form, action) {
                console.debug(action);
            },
            scope: this,
            waitMsg: 'Aguarde ...'
        });
    },

    constructor: function(cfg) {
        if(!cfg) cfg = {}

        Ext.apply(
            cfg,
            {
                title: 'Carregar arquivos de retorno do eSocial',
                closable: true,
                resizable: false,
                width: 500,
                border: false,
                modal: true,
                items: [
                    this.getFormPanel(cfg),
                ],
                buttons: [
                    {
                        text: 'Carregar',
                        scope: this,
                        handler: this.execute
                    },
                    {
                        text: 'Cancelar',
                        scope: this,
                        handler: this.destroy
                    }
                ]
            }
        );

        esocial.qualification.LoaderFile.superclass.constructor.call(this, cfg);
    }
});


